/*
 * A320342  Maximum term in Cunningham chain of the first kind generated by
 *          the n-th prime.
 * https://oeis.org/A320342
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 70, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Algorithm: for a given index n (1‑based), find the n‑th prime pₙ,
   then repeatedly compute next = 2*current+1 while next is prime.
   Return the last prime reached. */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* Size of the sieve (enough for n up to around 1.5×10⁵, and certainly for n=10 000). */
static const size_t SIEVE_LIMIT = 2000000U;

/* Prime sieve and list (static, initialized on first call). */
static bool *sieve = NULL;
static uint32_t *prime_list = NULL;
static size_t prime_count = 0;
static bool sieve_initialized = false;

/* One‑time initialization of the sieve and prime array. */
static void init_sieve(void)
{
    size_t i, j;

    sieve = (bool *)malloc((SIEVE_LIMIT + 1) * sizeof(bool));
    if (!sieve)
        return;                       /* allocation failed – caller will handle */

    for (i = 0; i <= SIEVE_LIMIT; ++i)
        sieve[i] = true;
    sieve[0] = sieve[1] = false;

    for (i = 2; i * i <= SIEVE_LIMIT; ++i) {
        if (sieve[i]) {
            for (j = i * i; j <= SIEVE_LIMIT; j += i)
                sieve[j] = false;
        }
    }

    /* Count primes up to SIEVE_LIMIT. */
    for (i = 2, prime_count = 0; i <= SIEVE_LIMIT; ++i)
        if (sieve[i])
            ++prime_count;

    /* Store primes in an array. */
    prime_list = (uint32_t *)malloc(prime_count * sizeof(uint32_t));
    if (!prime_list)
        return;                       /* allocation failed – caller will handle */

    for (i = 2, j = 0; i <= SIEVE_LIMIT; ++i)
        if (sieve[i])
            prime_list[j++] = (uint32_t)i;
}

/* Wrapper for primality test that works for seq_t values. */
static bool is_prime_seq(seq_t x)
{
    /* If the number is within the sieve range, use the pre‑computed table. */
    if ((seq_t)SIEVE_LIMIT >= 0 && x <= (seq_t)SIEVE_LIMIT)
        return sieve[(size_t)x];

    /* Otherwise fall back to trial division using the primes we have. */
    uint64_t ux = (uint64_t)x;
    for (size_t k = 0; k < prime_count; ++k) {
        uint64_t p = (uint64_t)prime_list[k];
        if (p * p > ux)
            break;
        if (ux % p == 0)
            return false;
    }
    return true;
}

/* --------------------------------------------------------------------- */
/* Main OEIS sequence function                                       */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n < 1)
        return 0;   /* undefined for indices < 1 */

    /* Ensure the sieve has been built once. */
    if (!sieve_initialized) {
        init_sieve();
        sieve_initialized = true;
    }

    /* Safety check – if n exceeds the number of primes we pre‑computed,
       the function cannot proceed. For the expected range (n ≤ 10 000) this
       never occurs. */
    if ((size_t)n > prime_count)
        return 0;

    seq_t current = (seq_t)prime_list[(size_t)n - 1];   /* n‑th prime */

    while (true) {
        seq_t next = current * 2 + 1;
        if (is_prime_seq(next))
            current = next;
        else
            break;
    }

    return current;
}
